#![no_std]
use soroban_sdk::{contract, contracterror, contractimpl, contracttype, token, Address, Env};

const DAY_IN_LEDGERS: u32 = 17_280;
const TTL_THRESHOLD: u32 = 30 * DAY_IN_LEDGERS;
const TTL_EXTEND_TO: u32 = 120 * DAY_IN_LEDGERS;

#[contracttype]
#[derive(Clone)]
pub enum DataKey {
    Token,
    Total,
    Staked(Address),
}

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq)]
#[repr(u32)]
pub enum Error {
    AmountNotPositive = 1,
    InsufficientStake = 2,
}

/// Holds a Stellar token (the native XLM asset through its Stellar Asset Contract) on behalf of
/// stakers. The token address is fixed at deploy time by the constructor.
#[contract]
pub struct Staking;

#[contractimpl]
impl Staking {
    pub fn __constructor(env: Env, token: Address) {
        env.storage().instance().set(&DataKey::Token, &token);
        env.storage().instance().set(&DataKey::Total, &0i128);
        env.storage().instance().extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
    }

    /// Transfers `amount` from `user` into the contract and credits it to `user`.
    pub fn stake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::AmountNotPositive);
        }

        token_client(&env).transfer(&user, &env.current_contract_address(), &amount);

        let key = DataKey::Staked(user.clone());
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        env.storage().persistent().set(&key, &(staked + amount));
        env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);

        let total = total_staked(&env);
        env.storage().instance().set(&DataKey::Total, &(total + amount));
        env.storage().instance().extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);
        Ok(())
    }

    /// Returns `amount` of `user`'s stake to `user`. Fails if `user` has less than `amount` staked.
    pub fn unstake(env: Env, user: Address, amount: i128) -> Result<(), Error> {
        user.require_auth();
        if amount <= 0 {
            return Err(Error::AmountNotPositive);
        }

        let key = DataKey::Staked(user.clone());
        let staked: i128 = env.storage().persistent().get(&key).unwrap_or(0);
        if staked < amount {
            return Err(Error::InsufficientStake);
        }
        env.storage().persistent().set(&key, &(staked - amount));
        env.storage().persistent().extend_ttl(&key, TTL_THRESHOLD, TTL_EXTEND_TO);

        let total = total_staked(&env);
        env.storage().instance().set(&DataKey::Total, &(total - amount));
        env.storage().instance().extend_ttl(TTL_THRESHOLD, TTL_EXTEND_TO);

        token_client(&env).transfer(&env.current_contract_address(), &user, &amount);
        Ok(())
    }

    /// The amount `user` has staked.
    pub fn staked(env: Env, user: Address) -> i128 {
        env.storage().persistent().get(&DataKey::Staked(user)).unwrap_or(0)
    }

    /// The amount staked by everyone.
    pub fn total_staked(env: Env) -> i128 {
        total_staked(&env)
    }
}

fn total_staked(env: &Env) -> i128 {
    env.storage().instance().get(&DataKey::Total).unwrap_or(0)
}

fn token_client(env: &Env) -> token::TokenClient<'_> {
    let token: Address = env.storage().instance().get(&DataKey::Token).unwrap();
    token::TokenClient::new(env, &token)
}

mod test;
EOF
cat > src/test.rs <<'EOF'
#![cfg(test)]

use super::*;
use soroban_sdk::{
    testutils::Address as _,
    token::{StellarAssetClient, TokenClient},
    Address, Env,
};

struct Fixture {
    env: Env,
    staking: Address,
    token: Address,
}

fn fixture() -> Fixture {
    let env = Env::default();
    env.mock_all_auths();
    let admin = Address::generate(&env);
    let token = env.register_stellar_asset_contract_v2(admin).address();
    let staking = env.register(Staking, (token.clone(),));
    Fixture { env, staking, token }
}

fn fund(f: &Fixture, user: &Address, amount: i128) {
    StellarAssetClient::new(&f.env, &f.token).mint(user, &amount);
}

#[test]
fn stake_moves_tokens_into_the_contract() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let token = TokenClient::new(&f.env, &f.token);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 1_000);

    client.stake(&alice, &400);

    assert_eq!(client.staked(&alice), 400);
    assert_eq!(client.total_staked(), 400);
    assert_eq!(token.balance(&alice), 600);
    assert_eq!(token.balance(&f.staking), 400);
}

#[test]
fn stakes_add_up_per_user_and_in_total() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    let bob = Address::generate(&f.env);
    fund(&f, &alice, 1_000);
    fund(&f, &bob, 500);

    client.stake(&alice, &300);
    client.stake(&alice, &200);
    client.stake(&bob, &50);

    assert_eq!(client.staked(&alice), 500);
    assert_eq!(client.staked(&bob), 50);
    assert_eq!(client.total_staked(), 550);
}

#[test]
fn unstake_returns_tokens_to_the_user() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let token = TokenClient::new(&f.env, &f.token);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 1_000);
    client.stake(&alice, &400);

    client.unstake(&alice, &150);

    assert_eq!(client.staked(&alice), 250);
    assert_eq!(client.total_staked(), 250);
    assert_eq!(token.balance(&alice), 750);
    assert_eq!(token.balance(&f.staking), 250);
}

#[test]
fn unstaking_everything_leaves_nothing_staked() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);
    client.stake(&alice, &100);

    client.unstake(&alice, &100);

    assert_eq!(client.staked(&alice), 0);
    assert_eq!(client.total_staked(), 0);
}

#[test]
fn unstaking_more_than_staked_fails_and_changes_nothing() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let token = TokenClient::new(&f.env, &f.token);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);
    client.stake(&alice, &100);

    assert!(client.try_unstake(&alice, &101).is_err());

    assert_eq!(client.staked(&alice), 100);
    assert_eq!(client.total_staked(), 100);
    assert_eq!(token.balance(&f.staking), 100);
}

#[test]
fn unstaking_without_any_stake_fails() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);

    assert!(client.try_unstake(&alice, &1).is_err());
}

#[test]
fn non_positive_amounts_are_rejected() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);

    assert!(client.try_stake(&alice, &0).is_err());
    assert!(client.try_stake(&alice, &-5).is_err());
    assert_eq!(client.total_staked(), 0);
}

#[test]
fn stake_and_unstake_require_the_user_to_authorize() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);
    client.stake(&alice, &100);

    // No authorization for the next calls: the user's require_auth must reject them.
    f.env.set_auths(&[]);

    assert!(client.try_stake(&alice, &10).is_err());
    assert!(client.try_unstake(&alice, &10).is_err());
    assert_eq!(client.staked(&alice), 100);
}
