    assert_eq!(client.total_staked(), 100);
    assert_eq!(token.balance(&f.staking), 100);
}

#[test]
fn unstaking_without_any_stake_fails() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);

    assert!(client.try_unstake(&alice, &1).is_err());
}

#[test]
fn non_positive_amounts_are_rejected() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);

    assert!(client.try_stake(&alice, &0).is_err());
    assert!(client.try_stake(&alice, &-5).is_err());
    assert_eq!(client.total_staked(), 0);
}

#[test]
fn stake_and_unstake_require_the_user_to_authorize() {
    let f = fixture();
    let client = StakingClient::new(&f.env, &f.staking);
    let alice = Address::generate(&f.env);
    fund(&f, &alice, 100);
    client.stake(&alice, &100);

    // No authorization for the next calls: the user's require_auth must reject them.
    f.env.set_auths(&[]);

    assert!(client.try_stake(&alice, &10).is_err());
    assert!(client.try_unstake(&alice, &10).is_err());
    assert_eq!(client.staked(&alice), 100);
}
